from collections import Counter

def transform(grid):
    h, w = len(grid), len(grid[0])
    bg = Counter(v for row in grid for v in row).most_common(1)[0][0]
    points = [(r, c, grid[r][c]) for r in range(h) for c in range(w) if grid[r][c] != bg]
    if not points:
        return [row[:] for row in grid]
    # The pattern shifts down by one row, leaving the first row as background.
    out = [[bg for _ in range(w)] for _ in range(h)]
    for r, c, color in points:
        if r + 1 < h:
            out[r + 1][c] = color
    return out

